import{_ as a,o as e,c as r,ag as i}from"./chunks/framework.D9ghT4bC.js";const b=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Privacy-Policy.md","filePath":"zh/Privacy-Policy.md"}'),l={name:"zh/Privacy-Policy.md"};function d(o,t,h,n,s,c){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>本政策适用于 UncivCN 社区提供的服务：本文档站、社区下载服务器与社区联机服务器。这些服务由社区维护者以个人身份自建、自维护，<strong>与 Unciv 上游项目及其开发者（yairm210 团队，<a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a>）无关，也不代表任何官方服务</strong>。社区维护者是这些服务的数据控制者。</p><p>问题咨询、数据导出与删除请求：<a href="https://qm.qq.com/q/j92c3iUnZ0" target="_blank" rel="noreferrer">QQ 群</a> 或 <a href="https://github.com/AutumnPizazz/Unciv/issues" target="_blank" rel="noreferrer">GitHub Issues</a>。</p><h2 id="我们会存储什么" tabindex="-1">我们会存储什么 <a class="header-anchor" href="#我们会存储什么" aria-label="Permalink to &quot;我们会存储什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>用途</th><th>保存时长</th></tr></thead><tbody><tr><td>玩家 ID 与密码哈希</td><td>登录联机服务器。玩家 ID 由游戏客户端生成，密码只以加盐哈希保存</td><td>直到你请求删除账号</td></tr><tr><td>最后活跃时间</td><td>显示在线状态、清理长期不用的数据</td><td>直到删除账号</td></tr><tr><td>IP 地址</td><td>防滥用与限流。默认只保留网段（IPv4 <code>/24</code>、IPv6 <code>/48</code>）</td><td>默认 30 天，到期自动清空；服务器可以配置为完全不存</td></tr><tr><td>联机存档</td><td>供同局的其他玩家获取当前回合</td><td>长期无人使用的对局会在服务器空间紧张时加密归档到别处；归档的对局仍可按请求恢复，也可以请求彻底删除</td></tr><tr><td>访问日志（IP、User-Agent）</td><td>安全防护与故障排查</td><td>在服务器上短期保留，不对外提供</td></tr></tbody></table><p>密码以 <code>scrypt</code> 哈希保存，每个账号使用独立随机盐：包括管理员在内任何人都无法还原出明文，管理员只能重置密码。</p><h2 id="我们不会存储什么" tabindex="-1">我们不会存储什么 <a class="header-anchor" href="#我们不会存储什么" aria-label="Permalink to &quot;我们不会存储什么&quot;">​</a></h2><ul><li>不收集真实姓名、证件号、手机号或邮箱，本服务不要求提供身份信息。</li><li>不收集支付信息与广告标识：这些服务免费且非商业运营。</li><li>不会出售或向第三方提供数据；文档站不接入统计或追踪脚本。</li><li>不面向未成年人收集个人信息：本服务仅面向年满 18 周岁的成年人，我们不会主动向未成年人提供服务、也不会主动收集未成年人的个人信息。</li></ul><h2 id="你的选择" tabindex="-1">你的选择 <a class="header-anchor" href="#你的选择" aria-label="Permalink to &quot;你的选择&quot;">​</a></h2><ul><li><strong>换用其他服务器</strong>：在游戏「选项 → 高级」中设置自己的联机服务器地址，也可以在那里导入自己的玩家 ID。</li><li><strong>导出或删除数据</strong>：在 QQ 群或 GitHub Issues 中提出，我们会提供存档导出并删除你的账号与数据。</li><li>游戏的其他数据（设置、单机存档）都保存在你自己的设备上，服务器只能看到联机客户端上传的内容。</li><li>未成年人未经监护人同意注册的，可联系我们删除账号。</li></ul><h2 id="第三方" tabindex="-1">第三方 <a class="header-anchor" href="#第三方" aria-label="Permalink to &quot;第三方&quot;">​</a></h2><ul><li>文档站托管在 GitHub Pages，访问时也会经过 GitHub 的服务器。</li><li>模组与安装包可能从你在游戏里配置的镜像下载，这些服务有各自的隐私政策。</li><li>你访问 GitHub Pages、GitHub Releases 或镜像下载安装包，是自行直接访问这些第三方服务；社区服务端不会因此把你的个人信息发送到境外。</li><li>视可用性，服务器可能部署在中国大陆以外，数据在服务器所在地处理。</li></ul><h2 id="安全与限制" tabindex="-1">安全与限制 <a class="header-anchor" href="#安全与限制" aria-label="Permalink to &quot;安全与限制&quot;">​</a></h2><p>我们使用 HTTPS、密码哈希与访问控制，但这些是由志愿者维护的服务，按「现状」提供。我们无法承诺可用性、绝对保密或数据永不丢失，请为你重视的存档保留本地备份。</p><p>本政策的变更会记录在<a href="/Unciv/zh/UncivCN/Changelog.html">更新日志</a>中；服务的使用规则见<a href="/Unciv/zh/Terms-of-Service.html">用户协议</a>。</p>',15)])])}const m=a(l,[["render",d]]);export{b as __pageData,m as default};
